def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0
        if hp <= 3 or no_water >= 1:
            base = 40.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    danger_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 80:
                danger_bids.append(float(bid))
        if opp.get('budget', 0) >= 700 and opp.get('hp', 0) >= 5:
            rich_aggressive += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    likely_units = int(supply / WATER_REQ)

    if hp <= 2 or no_water >= 2:
        bid = 108.0 if likely_units <= 1 else 92.0
    elif hp <= 4 or no_water >= 1:
        bid = 88.0 if max_prev >= 90 else 72.0
    else:
        if likely_units >= 2:
            bid = 34.0
            if max_prev >= 100:
                bid = 28.0
            elif avg_prev >= 80:
                bid = 31.0
            if desperate_count >= 2:
                bid += 8.0
        else:
            bid = 58.0
            if max_prev >= 100:
                bid = 66.0
            elif max_prev >= 80:
                bid = 62.0
            if rich_aggressive >= 2:
                bid += 6.0

    if day >= 8:
        if hp <= 5:
            bid += 12.0
        else:
            bid += 5.0

    if budget < 120:
        bid = min(bid, budget)
    elif budget < 220:
        bid = min(bid, 0.7 * budget)

    floor_bid = 12.0
    if hp <= 4 or no_water >= 1:
        floor_bid = 25.0
    if hp <= 2 or no_water >= 2:
        floor_bid = 45.0

    bid = max(floor_bid, bid)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_survivors = len(alive_opponents) + 1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
    max_prev_bid = max(yesterday_bids)

    # If supply is tight, bid to beat the average. If supply is abundant, bid moderately.
    if supply < (num_survivors * WATER_REQ * 1.1):
        return min(my_status['budget'], max_prev_bid + 2.0)
    else:
        return min(my_status['budget'], avg_prev_bid * 0.95)
